using Planner.Core;
using Planner.Data;
using System.Reflection;
static class TransferTests
{
 static void Eq<T>(T want,T got){if(!Equals(want,got))throw new Exception($"expected {want}, got {got}");}
 static PlannerState Apply(PlannerState before,RepositoryPlan plan,string table)=>(PlannerState)(typeof(PlannerState).Assembly.GetType("Planner.Core.GeneratedPlanService")??throw new Exception("缺少生成交通记录的原子保存逻辑")).GetMethod("Apply")!.Invoke(null,[before,plan,table])!;
 static (PlannerState Before,RepositoryPlan Plan) Build()
 {
  var s=new PlannerState();s.Tables.Add(new(){Id="t",Name="测试表"});var a=new Place{Id="lake",Name="玄武湖",Lng=118.8,Lat=32.07};var b=new Place{Id="temple",Name="夫子庙",Lng=118.78,Lat=32.02};var day=new DateOnly(2026,10,30);
  return(s,RepositoryPlanner.PlanAsync(s,[new(new(){Day=day,Title="玄武湖游玩",Location=a.Name,Start=600,Duration=240},a),new(new(){Day=day,Title="夫子庙游览",Location=b.Name,Duration=30,ModeIn="公交"},b)],(_,_,_,depart,_)=>{Eq(day.ToDateTime(new(14,0)),depart);return Task.FromResult(new TravelEstimate(35,"公交 · 交通测试快照"));}).GetAwaiter().GetResult());
 }
 public static void Register(Action<string,Action> test)
 {
  test("confirmed outgoing transfer to existing stop is saved and undone with its generated batch",()=>{var s=new PlannerState();s.Tables.Add(new(){Id="t"});var a=new Place{Id="a",Name="玄武湖"};var b=new Place{Id="b",Name="南京图书馆"};s.Places.Add(b);s.Activities.Add(new(){Id="existing",TableId="t",Title="已有预约",PlaceId=b.Id,StartAt=new(2026,10,30,12,0,0),EndAt=new(2026,10,30,13,0,0)});var plan=RepositoryPlanner.PlanAsync(s,[new(new(){Day=new(2026,10,30),Title="新增游览",Location=a.Name,Start=600,Duration=60},a)],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(25,"步行测试"))).GetAwaiter().GetResult();var after=Apply(s,plan,"t");Eq(1,after.Legs.Count);Eq("existing",after.Legs[0].ToActivityId);Eq(new DateTime(2026,10,30,11,0,0),after.Legs[0].DepartAt);Eq(4,BoardProjection.Range(after,new(2026,10,30),new(2026,10,31)).Single().Entries.Count+1);var undone=GeneratedBatchService.Undo(after,GeneratedBatchService.Capture(s,after,"branch"));Eq("existing",undone.Activities.Single().Id);Eq(0,undone.Legs.Count);});
  test("final adjacency stores each real transfer once and omits bypassed provisional after leg",()=>{var s=new PlannerState();s.Tables.Add(new(){Id="t"});var b=new Place{Id="b",Name="既有终点"};s.Places.Add(b);s.Activities.Add(new(){Id="existing",TableId="t",PlaceId=b.Id,Title="晚间预约",StartAt=new(2026,10,30,17,0,0),EndAt=new(2026,10,30,18,0,0)});var plan=RepositoryPlanner.PlanAsync(s,[new(new(){Day=new(2026,10,30),Title="A",Location="A",Start=600,Duration=60},new(){Id="a",Name="A"}),new(new(){Day=new(2026,10,30),Title="C",Location="C",Start=780,Duration=30},new(){Id="c",Name="C"})],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(20,"测试交通"))).GetAwaiter().GetResult();var after=Apply(s,plan,"t");Eq(2,after.Legs.Count);var aid=after.Activities.Single(x=>x.Title=="A").Id;Eq(false,after.Legs.Any(l=>l.FromActivityId==aid&&l.ToActivityId=="existing"));});
  test("traffic labels use the actual recurring occurrence place override",()=>{var s=new PlannerState();s.Tables.Add(new(){Id="t"});s.Places.AddRange([new(){Id="default",Name="周期默认地点"},new(){Id="override",Name="南京图书馆"}]);s.Activities.Add(new(){Id="weekly",TableId="t",Title="周期会议",PlaceId="default",Kind="WEEKLY",DurationMin=60});s.Rules.Add(new(){ActivityId="weekly",ValidFrom=new(2026,10,1),WeekMask=16,StartTime="09:00"});s.Exceptions.Add(new(){ActivityId="weekly",OriginDate=new(2026,10,30),StartAt=new(2026,10,30,9,0,0),EndAt=new(2026,10,30,10,0,0),PlaceOverride=true,PlaceId="override"});var p=new Place{Id="dest",Name="夫子庙"};var plan=RepositoryPlanner.PlanAsync(s,[new(new(){Day=new(2026,10,30),Title="后续游览",Location=p.Name,Start=660,Duration=30},p)],(from,_,_,_,_)=>{Eq("override",from.Id);return Task.FromResult(new TravelEstimate(20,"测试"));}).GetAwaiter().GetResult();var after=Apply(s,plan,"t");var card=BoardProjection.Range(after,new(2026,10,30),new(2026,10,31)).Single().Entries.Single(x=>x.Transfer is not null);Eq(true,card.Occurrence.Title.Contains("南京图书馆 → 夫子庙"));});
  test("ordered stop uses first finish plus travel plus full requested dwell",()=>{var (_,p)=Build();Eq(875,p.Rows[1].Start);Eq(30,p.Rows[1].Trip.Request.Duration);});
  test("generated travel is persisted separately and displayed without duplicate activities",()=>{var(s,p)=Build();var after=Apply(s,p,"t");Eq(2,after.Activities.Count);Eq(1,after.Legs.Count);Eq(new DateTime(2026,10,30,14,0,0),after.Legs[0].DepartAt);Eq(new DateTime(2026,10,30,14,35,0),after.Legs[0].ArriveAt);Eq("UNVERIFIED",after.Legs[0].ValidationStatus);var folder=Path.Combine(Path.GetTempPath(),"transfer-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{var db=new SqliteStore(Path.Combine(folder,"planner.db"));db.Save(after,0);var loaded=db.Load();Eq(3,BoardProjection.Range(loaded,new(2026,10,30),new(2026,10,31)).Single().Entries.Count);Eq(0,BoardProjection.Range(loaded,new(2026,10,30),new(2026,10,31),Array.Empty<string>()).Single().Entries.Count);Eq(35,loaded.Segments.Single().DurationSec/60);}finally{Directory.Delete(folder,true);}});
  test("owned travel receipts survive restart and scoped undo keeps unrelated same day inserts",()=>{var(s,p)=Build();var after=Apply(s,p,"t");var receipt=GeneratedBatchService.Capture(s,after,"branch");var chat=new GuidedConversation();chat.Batches.Add(receipt);var folder=Path.Combine(Path.GetTempPath(),"transfer-chat-"+Guid.NewGuid());try{var store=new ConversationStore(folder);store.Save(chat);receipt=store.Load().Batches.Single();var later=ChangeService.Apply(after,[new(){Activity=new(){Id="later",TableId="t",Title="手动晚餐",StartAt=new(2026,10,30,18,0,0),EndAt=new(2026,10,30,19,0,0)}}],after.Revision);Eq("STALE",later.Legs.Single().ValidationStatus);var undone=GeneratedBatchService.Undo(later,receipt);Eq("later",undone.Activities.Single().Id);Eq(0,undone.Legs.Count);Eq(0,undone.Plans.Count);Eq(0,undone.Segments.Count);}finally{if(Directory.Exists(folder))Directory.Delete(folder,true);}});
  test("undo refuses changed generated travel or new external legs",()=>{var(s,p)=Build();var after=Apply(s,p,"t");var receipt=GeneratedBatchService.Capture(s,after,"branch");var changed=after.Copy();changed.Legs[0].ArriveAt=changed.Legs[0].ArriveAt.AddMinutes(2);bool denied=false;try{GeneratedBatchService.Undo(changed,receipt);}catch(InvalidOperationException){denied=true;}Eq(true,denied);changed=after.Copy();changed.Segments[0].Geometry="changed";denied=false;try{GeneratedBatchService.Undo(changed,receipt);}catch(InvalidOperationException){denied=true;}Eq(true,denied);changed=after.Copy();changed.Legs.Add(new(){PlanId=changed.Plans[0].Id,ToActivityId=changed.Activities[0].Id});denied=false;try{GeneratedBatchService.Undo(changed,receipt);}catch(InvalidOperationException){denied=true;}Eq(true,denied);});
  test("generated transfer reuses existing unique daily plan and undo preserves it",()=>{var(s,p)=Build();s.Plans.Add(new(){Id="existing",PlanDate=new(2026,10,30),Status="STALE"});var after=Apply(s,p,"t");Eq(1,after.Plans.Count);Eq("existing",after.Legs.Single().PlanId);var receipt=GeneratedBatchService.Capture(s,after,"branch");var undone=GeneratedBatchService.Undo(after,receipt);Eq("existing",undone.Plans.Single().Id);Eq(0,undone.Legs.Count);});
  test("travel cards split across midnight without reserving another user activity",()=>{var(s,p)=Build();var after=Apply(s,p,"t");after.Legs[0].DepartAt=new(2026,10,30,23,50,0);after.Legs[0].ArriveAt=new(2026,10,31,0,20,0);var projection=BoardProjection.Range(after,new(2026,10,30),new(2026,11,1));Eq(3,projection[0].Entries.Count);Eq(1,projection[1].Entries.Count);Eq(10,projection[0].Entries.Last().DayMinutes);Eq(20,projection[1].Entries.Single().DayMinutes);Eq(2,after.Activities.Count);});
 }
}
